	var dp [501][501]int64
	for i := 2; i <= n; i++ {
		jj := Min(x, i-1)
		for j := 1; j <= jj; j++ {
			// dp[i][j] = j^i - (j-1)^i
			dp[i][j] = pow[j][i] - pow[j-1][i]
			dp[i][j] %= Mod
		}
	}

	for i := 2; i <= n; i++ {
		for j := 1; j <= x; j++ {
			if dp[i][j] == 0 {
				continue
			}
			for k := 0; k <= n-i; k++ {
				nj := j + i + k - 1
				if nj > x {
					break
				}
				dp[i+k][nj] += dp[i][j] * pow[i+k-1][k] % Mod * ModCombination(i+k, k)
				dp[i+k][nj] %= Mod
			}
		}
	}

	ans := int64(0)
	for j := 1; j <= x; j++ {
		ans += dp[n][j]
		ans %= Mod
	}
	println(((ans % Mod) + Mod) % Mod)
}

func ModCombination(n, k int) (ret int64) {
	if n < k {
		return 0
	}
	for ret = 1; n > 0 || k > 0; n, k = n/Mod, k/Mod {
		ret = ret * fac[n%Mod] % Mod * finv[k%Mod] % Mod * finv[(n-k)%Mod] % Mod
	}
	return
}

const MAX = 500

var fac, finv, inv [MAX + 1]int64

func init() {
	fac[int64(0)], fac[int64(1)], finv[int64(0)], finv[int64(1)], inv[int64(1)] = int64(1), int64(1), int64(1), int64(1), int64(1)
	for i := int64(2); i <= MAX; i++ {
		fac[i], inv[i] = fac[i-int64(1)]*i%Mod, Mod-inv[Mod%i]*(Mod/i)%Mod
		finv[i] = finv[i-int64(1)] * inv[i] % Mod
	}
}

func Min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

